import { useParams } from 'react-router-dom';


function TrainDetails() {
  const { train_number } = useParams();
  const fetchTrainRoute =async () => {
    const response = await fetch(`https://rappid.in/apis/train.php?train_no=${train_number}`)
    if(response['success'] === false){
      <h1>Train is not running today</h1>
    }
    else{
      <h1>Train is running today</h1>
    }
  }
